cat > /tmp/Probe.java << 'EOF'
import org.apache.commons.csv.CSVFormat;
import org.apache.commons.csv.QuoteMode;
import java.io.StringWriter;

public class Probe {
    public static void main(String[] args) throws Exception {
        CSVFormat format = CSVFormat.DEFAULT.builder().setNullString("NULL").setQuoteMode(QuoteMode.ALL).get();
        StringWriter w = new StringWriter();
        format.print(null, w, true);
        System.out.println("[" + w.toString() + "]");
    }
}
EOF
CP="target/classes"
javac -cp "$CP" -d /tmp/out2 /tmp/Probe.java
java -cp "/tmp/out2:$CP" Probe
